import {mountBatchControls} from '/batch-controls.mjs';
import {referenceForm,pricingMarkup,genericMarkup,designFee,artworkHTML,choiceLines} from '/pricing-form.mjs';
import {garmentPhoto} from '/apparel-ui.mjs';
import {mountProductExtras} from '/services-ui.mjs';
import {PRODUCTS,priceInputs} from './model.mjs';import {priceHTML,studioAPI} from './api.mjs';import {observeTranslations,translateTree,localizedPath,registerRuleTranslations} from './i18n.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountPricingForm(root,actions={}){const page=location.pathname.replace(/\/$/,''),canonical=page.replace(/^\/satin\/(fa|fr|es)(?=\/|$)/,'/satin');const embedded=root.querySelector('[data-pricing-bootstrap]');let rule,catalogData;if(embedded&&embedded.dataset.path===canonical){const seed=JSON.parse(embedded.textContent);rule=seed.rule;catalogData={products:seed.configured?[seed.configured]:[]};}else{const [r,pr]=await Promise.all([fetch('/api/rules?path='+encodeURIComponent(page)),Promise.resolve(null)]);if(!r.ok){root.querySelector('.pricing-pending')?.classList.remove('pricing-pending');return;}const seed=await r.json();rule=seed.rule;catalogData={products:seed.configured?[seed.configured]:[],unavailablePaths:seed.unavailablePaths||[]};}if(catalogData.unavailablePaths?.includes(canonical)){const original=root.querySelector('.cfg,.rule-cfg');if(original)original.innerHTML='<p>Product unavailable</p>';translateTree(root);return;}const catalog=catalogData.products;let configured=catalog.find(p=>p.path===canonical);if(['glass-frosted-vinyl','tint-commercial','tint-vehicle'].includes(rule?.id))configured={...configured,artwork:false,studioProductId:''};if(configured&&configured.ruleId!==rule?.id){const rr=await fetch('/api/rules?id='+configured.ruleId);if(rr.ok)rule=(await rr.json()).rule;}if(!rule){root.querySelector('.pricing-pending')?.classList.remove('pricing-pending');return;}if(page!==location.pathname.replace(/\/$/,'')||!root.isConnected)return;if(!rule.quantityKeys&&configured?.images?.length){const hero=root.querySelector('.art.photo img');if(hero){for(const source of hero.closest('picture')?.querySelectorAll('source')||[])source.remove();hero.removeAttribute('srcset');hero.src=configured.images[0];hero.alt=configured.name;}}registerRuleTranslations(rule);let old=root.querySelector('.cfg,.rule-cfg');if(!old){const section=document.createElement('section');section.className='sec';const wrap=document.createElement('div');wrap.className='wrap';old=document.createElement('div');wrap.append(old);section.append(wrap);root.querySelector('.page-enter')?.append(section);}if(!document.querySelector('[data-studio-css]')){const l=document.createElement('link');l.rel='stylesheet';l.href='/studio/designer.css';l.dataset.studioCss='';document.head.append(l);}const special=referenceForm(rule),fee=designFee(rule);let serial=0,quote=null,values=Object.fromEntries(rule.fields.map(f=>[f.key,f.default])),artwork=null,upload=null,uploads=[],mode='upload';const params=new URLSearchParams(location.search);try{const saved=JSON.parse(params.get('values')||'{}');for(const f of rule.fields)if(saved[f.key]!==undefined)values[f.key]=Number(saved[f.key]);}catch{}values.design=0;
root.addEventListener('click',e=>{if(e.target.closest('[data-checkout-jump]')){e.preventDefault();e.stopPropagation();location.assign('/satin/checkout/');}});const box=document.createElement('div');box.className='rule-cfg';const product=PRODUCTS.find(p=>p.id===configured?.studioProductId)||PRODUCTS.find(p=>p.ruleId===rule.id);box.innerHTML=genericMarkup(rule,configured,values,product);if(special){box.className='rule-cfg reference-cfg';box.innerHTML=pricingMarkup(rule,configured,values);}old.replaceWith(box);const $=s=>box.querySelector(s),cleanup=observeTranslations(box);box._translationCleanup=cleanup;
function controls(){if(!$('[data-art-controls]'))return;if(mode==='upload'){const apparel=rule.id.startsWith('apparel-')||rule.id==='dtf-transfers',wall=rule.id==='wallpaper-custom',vector=rule.id==='wrap-prints';$('[data-art-controls]').innerHTML=`<input type="file" data-art-upload multiple accept="${apparel?'image/png,image/svg+xml':wall?'image/png,image/jpeg,image/webp':vector?'image/svg+xml,application/pdf':'image/png,image/jpeg,image/webp,application/pdf,image/svg+xml'}"><p class="small">${apparel?'PNG or SVG':wall?'Image files only':vector?'SVG or vector PDF at 1:1 scale':'PNG, JPG, WebP, SVG or PDF'} · maximum 20 MB per file</p><div data-file-checks></div><label class="artwork-consent"><input type="checkbox" data-art-accept> I confirm my files and understand that print quality or artwork issues remain my responsibility. Production review may identify further issues.</label><p class="small">Support: <a href="mailto:info@satingraphic.ca">info@satingraphic.ca</a></p>`;}if(mode==='designer')$('[data-art-controls]').innerHTML=`<p>Design services add $${fee} + applicable taxes. Our designer will contact you to discuss your brief.</p>`;if(mode==='studio')$('[data-art-controls]').innerHTML=`<p>Create your artwork in Design Studio, then return here to finish your order.</p><a class="btn ghost" data-studio-link>Open Design Studio</a>`;updateLink();}
function updateLink(){const link=$('[data-studio-link]');if(link){const query=new URLSearchParams({product:product.id,returnTo:page,values:JSON.stringify(values)});if(artwork)query.set('designId',artwork.id);link.href=product.garment?.category==='t-shirts'?'https://satingraphic-apparel-studio.mehrad-tr.chatgpt.site/':localizedPath('/satin/design-studio')+'?'+query;}}
async function recalc(){const version=++serial;$('[data-rule-add]').disabled=true;try{const response=await fetch('/api/rules/quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:rule.id,values,coupon:$('[data-discount-code]').value})});const data=await response.json();if(version!==serial||!box.isConnected)return;if(!response.ok)throw Error(data.error);quote=data.quote;summary();$('[data-rule-price]').innerHTML=(rule.priceOnRequest||rule.customSizeValue!==undefined&&values.size===rule.customSizeValue)&&quote.subtotal<=(values.design?fee*100:0)?'<p>Product price on request</p>'+(values.design?`<p class="small">Design services: $${fee} + applicable tax. Product pricing will be added to your quote.</p>`:''):priceHTML(quote);$('[data-price-error]').textContent='';$('[data-rule-add]').disabled=configured?.stock===0;updateLink();}catch(e){if(version!==serial||!box.isConnected)return;quote=null;summary();$('[data-rule-price]').textContent='';$('[data-price-error]').textContent=e.message;}}
box.onchange=async e=>{if(e.target.dataset.rf){values[e.target.dataset.rf]=e.target.type==='checkbox'?+e.target.checked:Number(e.target.value);if(e.target.dataset.rf==='design'&&$('[name=artwork-mode]')){mode=e.target.checked?'designer':'upload';const radio=$('[name=artwork-mode][value='+mode+']');if(radio)radio.checked=true;controls();}summary();recalc();}if(e.target.name==='artwork-mode'){mode=e.target.value;if(rule.fields.some(f=>f.key==='design')){values.design=mode==='designer'?1:0;}controls();recalc();summary();box.dispatchEvent(new Event('design-mode-change'));}if(e.target.hasAttribute('data-art-upload')){const files=[...e.target.files];if(!files.length)return;try{if(files.some(f=>f.size>20000000))throw Error('Each upload must be smaller than 20 MB.');$('[data-art-status]').textContent='Saving artwork…';await studioAPI('session',{});uploads=[];for(const f of files){const fd=new FormData();fd.set('file',f);fd.set('product',rule.id);const r=await fetch('/api/studio/upload',{method:'POST',body:fd}),v=await r.json();if(!r.ok)throw Error(v.error);uploads.push(v.file);}upload=uploads[0];$('[data-art-status]').textContent=uploads.map(f=>f.name).join(' · ');artwork=null;$('[data-art-preview]').innerHTML='';const cr=await fetch('/api/artwork/check',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ruleId:rule.id,values,fileIds:uploads.map(f=>f.id)})}),checks=await cr.json();$('[data-file-checks]').innerHTML=(checks.reports||[]).map(r=>`<details open><summary>${esc(r.name)} · ${esc(r.status)}</summary><p>${esc(r.message||'File structure and dimensions checked; confirm colour, resolution and fonts before production.')}</p>${(r.pages||[]).map(p=>p.checks.map(c=>`<p>${esc(c.name)}: ${esc(c.detail)}</p>`).join('')).join('')}</details>`).join('');}catch(err){$('[data-art-status]').textContent=err.message;}}};box.oninput=e=>{if(e.target.dataset.rf&&e.target.type==='number'){values[e.target.dataset.rf]=Number(e.target.value);recalc();}};$('[data-apply-code]').onclick=recalc;
$('[data-rule-add]').onclick=async()=>{if(!quote)return;if(rule.id==='wrap-prints'&&values.kind===1&&values.height>48){$('[data-price-error]').textContent='Cut decals have a maximum height of 48 inches.';return;}if(upload&&!$('[data-art-accept]')?.checked){$('[data-price-error]').textContent='Confirm your artwork and responsibility for file issues before adding to cart.';return;}if((product?.group==='Offset print'||rule.customSizeValue!==undefined&&values.size===rule.customSizeValue)&&quote.subtotal<=(values.design?fee*100:0)){ $('[data-price-error]').textContent='Choose a standard size with an available price.';return;}const b=$('[data-rule-add]');b.disabled=true;try{const accepted=box._terms?.()||[];let reference='';if(artwork){const d=structuredClone(artwork.design);const previous=priceInputs(product,d.options,rule);for(const k of ['size','fold','corners','print_sides',...(rule.quantityKeys?['colour','placement','method']:product?.customSize?['width','height']:[])])if(Object.hasOwn(values,k)&&values[k]!==previous[k])throw Error('Product size or print sides changed. Reopen Design Studio and approve the updated design.');d.options.values={...d.options.values,...values};d.options.quantity=values.quantity||1;d.options.coupon=$('[data-discount-code]').value;await studioAPI('design',{id:artwork.id,design:d});const png=async role=>{const file=artwork.design.generated.find(f=>f.role===role),r=await fetch('/api/studio/file?id='+file.id+'&inline=1'),blob=await r.blob();return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});};const [preview,mockup]=await Promise.all([png('preview'),png('mockup')]);const added=await studioAPI('cart/add',{id:crypto.randomUUID(),designId:artwork.id,approved:true,expectedTotal:quote.total,expectedRevision:quote.revision,preview,mockup});reference='Design reference: '+added.id;}else if(mode==='studio')throw Error('Open Design Studio, generate and submit your design first.');else if(mode==='upload'&&!values.design&&(configured?.artwork??!!product)&&!upload)throw Error('Upload artwork, request a designer or create your design first.');if(rule.quantityKeys)accepted.unshift('Total garments: '+rule.quantityKeys.reduce((n,k)=>n+values[k],0));if(rule.priceOnRequest&&quote.subtotal<=(values.design?fee*100:0))accepted.unshift('Product price requires confirmation. Only known service charges are estimated.');const lines=rule.fields.filter(f=>f.key!=='design'||values.design).map(f=>`${f.key==='design'?'Design services':f.label}: ${f.type==='select'?selectedLabel(f):values[f.key]}`);lines.push(...accepted);if(reference)lines.push(reference);if(upload)lines.push('Artwork file: '+upload.id+' · '+upload.name);if(mode==='designer')lines.push('Design service requested');actions.add?.({name:configured?.name||rule.label,lines,pricePending:rule.priceOnRequest&&quote.subtotal<=(values.design?fee*100:0),total:quote.total/100,artworkAccepted:!!artwork||!!$('[data-art-accept]')?.checked||!configured?.artwork,artwork:artwork?{designId:artwork.id}:upload?{fileId:upload.id,fileIds:uploads.map(f=>f.id)}:null,pricing:{ruleId:rule.id,values,quote,coupon:quote.coupon||''}});if(!rule.priceOnRequest){location.assign('/satin/checkout/');return;}if($('[data-art-status]'))$('[data-art-status]').innerHTML='Product and artwork added to cart.'+(product?.group==='Offset print'&&mode!=='studio'?' <a href="/satin/checkout/" data-checkout-jump>Review artwork &amp; checkout</a>':'');}catch(err){$('[data-price-error]').textContent=err.message;}finally{b.disabled=false;}};
if(params.get('designId')){try{artwork=await studioAPI('attachment?id='+encodeURIComponent(params.get('designId')));if(artwork.design.productId!==product?.id)throw Error('Design does not match this product');mode='studio';const radio=box.querySelector('[name="artwork-mode"][value="studio"]');if(radio)radio.checked=true;controls();$('[data-art-preview]').innerHTML=`<img src="/api/studio/file?id=${artwork.design.generated.find(f=>f.role==='mockup').id}&inline=1" alt="Approved design mockup"><p>Approved design attached</p>`;}catch(err){artwork=null;$('[data-price-error]').textContent=err.message;}}
function selectedLabel(f){const selected=box.querySelector(`[data-rf="${f.key}"]:checked`);return f.options[Number(selected?.dataset.optionIndex??f.options.findIndex(o=>o.value===values[f.key]))]?.label||'';}
function summary(){const qb=box.querySelector('[data-quote]');if(qb){qb.dataset.estimate=JSON.stringify({product:configured?.name||rule.label,rule:rule.id,choices:rule.fields.map(f=>({label:f.label,value:f.type==='select'?selectedLabel(f):values[f.key]})),subtotal:quote?.subtotal,currency:'CAD'});}if(rule.quantityKeys){const colour=rule.fields.find(f=>f.key==='colour')?.options.find(o=>o.value===values.colour);const label=$('[data-selected-colour]');if(label)label.textContent=colour?.label||'';for(const img of [...box.querySelectorAll('.managed-product-gallery img:first-child'),...root.querySelectorAll('.apparel-product-hero img')]){const src=garmentPhoto(rule.id,values.colour);if(img.getAttribute('src')!==src){img.closest('picture')?.querySelectorAll('source').forEach(s=>s.remove());img.removeAttribute('srcset');img.src=src;img.alt=(configured?.name||rule.label)+' · '+colour?.label;}}}const stage=$('[data-reference-vehicle]');if(stage){const coverage=values.coverage??1;stage.querySelector('[data-ref-decal]').style.opacity=coverage<.3?'1':'0';stage.querySelector('[data-ref-wrap]').style.clipPath=coverage<.3?'inset(0 100% 0 0)':`inset(0 0 0 ${Math.round((1-(coverage===.45?.5:coverage===.7?.75:coverage))*100)}%)`;const label=rule.fields.find(f=>f.key==='coverage')?.options.find(o=>o.value===coverage)?.label||'';$('[data-reference-caption]').textContent=label+' · '+Math.round(coverage*100)+'% of full-wrap coverage price';}const total=$('[data-order-total]');if(!total)return;total.innerHTML=rule.priceOnRequest&&quote?.subtotal<=(values.design?fee*100:0)?'<b>Price on request</b>':`<b>${quote?new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format((special?quote.subtotal:quote.total)/100):'—'}</b><span>${special?'Before tax · CAD':'Total · CAD'}</span>`;$('[data-order-choices]').innerHTML=special?choiceLines(rule,values,Object.fromEntries(rule.fields.filter(f=>f.type==='select').map(f=>[f.key,selectedLabel(f)]))):rule.fields.filter(f=>f.key!=='design'||values.design).map(f=>`<div><span>${esc(f.label)}</span><strong>${esc(f.type==='select'?selectedLabel(f):f.key==='design'?('$'+fee):f.type==='checkbox'?(values[f.key]?'Yes':'No'):values[f.key])}</strong></div>`).join('');box.querySelectorAll('[data-quantity]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.quantity)===values.quantity)));}
box.addEventListener('click',e=>{const b=e.target.closest('[data-quantity]');if(!b)return;values.quantity=Number(b.dataset.quantity);$('[data-rf="quantity"]').value=values.quantity;summary();recalc();});
controls();mountBatchControls(box,rule,values,()=>{summary();recalc();});summary();await recalc();await mountProductExtras(box,rule,configured,()=>values);translateTree(box);}
